<?php
require_once dirname(__DIR__).'/includes/auth.php';$u=require_role('administrator');$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=(string)($_POST['action']??'');
 if($action==='create'){
  $role=(int)($_POST['role_id']??0);$faculty=(int)($_POST['faculty_id']??0)?:null;$dep=(int)($_POST['department_id']??0)?:null;$prog=(int)($_POST['programme_id']??0)?:null;$first=post_string('first_name',80);$last=post_string('last_name',80);$email=strtolower(post_string('email',190));$staff=strtoupper(post_string('staff_number',40));
  $q=db()->prepare('SELECT name FROM roles WHERE id=? AND name<>\'student\'');$q->execute([$role]);$roleName=$q->fetchColumn();
  if(!$roleName||!$first||!$last||!filter_var($email,FILTER_VALIDATE_EMAIL)||!$staff)$err='Enter the staff name, valid email, staff number, and role.';
  elseif($roleName==='dean'&&!$faculty)$err='Assign the Dean account to one faculty.';
  elseif(in_array($roleName,['supervisor','coordinator'],true)&&!$dep)$err='Assign supervisors and HOD accounts to a department.';
  elseif($prog&&!$dep)$err='Select a department before selecting a programme.';
  else{
   if($prog){$q=db()->prepare('SELECT department_id FROM programmes WHERE id=?');$q->execute([$prog]);if((int)$q->fetchColumn()!==$dep)$err='The selected programme does not belong to that department.';}
   if(!$err)try{$temp=bin2hex(random_bytes(5)).'aA1!';db()->beginTransaction();$q=db()->prepare('INSERT INTO users(role_id,faculty_id,department_id,programme_id,staff_number,first_name,last_name,email,password_hash,must_change_password) VALUES(?,?,?,?,?,?,?,?,?,1)');$q->execute([$role,$faculty,$dep,$prog,$staff,$first,$last,$email,password_hash($temp,PASSWORD_DEFAULT)]);$id=(int)db()->lastInsertId();if($roleName==='examiner')db()->prepare('INSERT INTO examiners(user_id) VALUES(?)')->execute([$id]);db()->commit();audit('user_created','user',$id,'Administrator created '.$roleName.' profile');$_SESSION['new_temp_password']=$temp;flash('success',ucfirst($roleName).' profile created. Copy the temporary password shown below.');redirect('admin/users.php?created='.$id);}catch(PDOException $e){if(db()->inTransaction())db()->rollBack();$err='Email or staff number is already in use.';}
  }
 }elseif($action==='toggle'){$id=(int)($_POST['user_id']??0);db()->prepare("UPDATE users SET account_status=IF(account_status='active','inactive','active') WHERE id=? AND id<>?")->execute([$id,$u['id']]);audit('user_status_changed','user',$id,'Account status toggled');flash('success','Account status updated.');redirect('admin/users.php');}
}
$roles=db()->query("SELECT id,name FROM roles WHERE name IN ('administrator','dean','coordinator','supervisor','examiner') ORDER BY id")->fetchAll();$deps=db()->query('SELECT d.id,d.name,f.name faculty FROM departments d JOIN faculties f ON f.id=d.faculty_id WHERE d.is_active=1 ORDER BY f.name,d.name')->fetchAll();$facList=db()->query('SELECT id,name FROM faculties WHERE is_active=1 ORDER BY name')->fetchAll();$users=db()->query('SELECT u.*,r.name role,d.name department,COALESCE(f.name,df.name) faculty FROM users u JOIN roles r ON r.id=u.role_id LEFT JOIN departments d ON d.id=u.department_id LEFT JOIN faculties f ON f.id=u.faculty_id LEFT JOIN faculties df ON df.id=d.faculty_id ORDER BY u.created_at DESC')->fetchAll();$pageTitle='User Management';$crumbTrail=['Admin','Users'];require dirname(__DIR__).'/includes/header.php';
?>
<?php $totalUsers=count($users);$activeUsers=count(array_filter($users,fn($x)=>$x['account_status']==='active')); ?><div class="row g-3 mb-3"><div class="col-md-4"><div class="stat-card"><div class="stat-label">Total users</div><div class="stat-value"><?= (int)$totalUsers ?></div><small class="stat-sub">All portal roles</small></div></div><div class="col-md-4"><div class="stat-card"><div class="stat-label">Active</div><div class="stat-value text-green"><?= (int)$activeUsers ?></div><small class="stat-sub"><?= $totalUsers?(int)round($activeUsers/$totalUsers*100):0 ?>% active</small></div></div><div class="col-md-4"><div class="stat-card"><div class="stat-label">Inactive</div><div class="stat-value" style="color:var(--muted)"><?= (int)($totalUsers-$activeUsers) ?></div><small class="stat-sub">Suspended or graduated</small></div></div></div><p class="page-intro">The Admin manages accounts across the system. Each Dean is linked to one faculty; each HOD and supervisor is linked to a department. HODs create their department supervisor profiles and register students in Student registration.</p>
<?php if(isset($_SESSION['new_temp_password'])): ?><div class="alert alert-warning"><strong>Temporary password (shown once):</strong> <code><?= e($_SESSION['new_temp_password']) ?></code>. Share it securely; the user must change it at first sign-in.</div><?php unset($_SESSION['new_temp_password']);endif; ?>
<?php if($err): ?><div role="alert" class="alert alert-danger"><?= e($err) ?></div><?php endif; ?>
<div class="card p-4 mb-4"><h2 class="section-heading">Create a staff profile</h2><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="create"><div class="row g-3"><div class="col-md-3"><label class="form-label">First name</label><input class="form-control" name="first_name" maxlength="80" required></div><div class="col-md-3"><label class="form-label">Last name</label><input class="form-control" name="last_name" maxlength="80" required></div><div class="col-md-3"><label class="form-label">Institutional email</label><input class="form-control" name="email" type="email" maxlength="190" required></div><div class="col-md-3"><label class="form-label">Staff number</label><input class="form-control" name="staff_number" maxlength="40" required></div><div class="col-md-4"><label class="form-label">Role</label><select class="form-select" name="role_id" required><option value="">Select</option><?php foreach($roles as $r): ?><option value="<?= (int)$r['id'] ?>"><?= e(match($r['name']){'administrator'=>'Admin','dean'=>'Dean','coordinator'=>'HOD',default=>ucfirst($r['name'])}) ?></option><?php endforeach; ?></select></div><div class="col-md-4"><label class="form-label">Faculty (required for Dean)</label><select class="form-select" name="faculty_id"><option value="">Select faculty</option><?php foreach($facList as $f): ?><option value="<?= (int)$f['id'] ?>"><?= e($f['name']) ?></option><?php endforeach; ?></select></div><div class="col-md-4"><label class="form-label">Department (required for HOD and supervisor)</label><select class="form-select" name="department_id"><option value="">Select department</option><?php foreach($deps as $d): ?><option value="<?= (int)$d['id'] ?>"><?= e($d['faculty'].' · '.$d['name']) ?></option><?php endforeach; ?></select></div><div class="col-12"><button class="btn btn-primary">Create staff profile</button></div></div></form></div>
<div class="card p-4"><div class="section-row mb-3"><h2 class="section-heading mb-0">Portal User Accounts</h2><label class="search-box m-0"><?= ui_icon('search') ?><input type="search" class="form-control" placeholder="Search records..." aria-label="Search accounts" data-live-filter="#usersTable tbody tr"></label></div><div class="table-responsive"><table class="table table-soft align-middle" id="usersTable"><thead><tr><th>Name / identifier</th><th>Email</th><th>Role</th><th>Academic unit</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($users as $person): ?><tr><td><?= e(trim(($person['first_name']??'').' '.($person['last_name']??''))?:'—') ?><br><small><?= e($person['staff_number']?:($person['matric_number']??'')) ?></small></td><td><?= e($person['email']??'—') ?></td><td><?= e(match($person['role']){'administrator'=>'Admin','dean'=>'Dean','coordinator'=>'HOD',default=>ucfirst($person['role'])}) ?></td><td><?= e(trim(($person['faculty']??'').' · '.($person['department']??''))?:'—') ?></td><td><?= status_badge($person['account_status']) ?></td><td><?php if((int)$person['id']!==(int)$u['id']): ?><form method="post" data-confirm="Change this account's active status?"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="user_id" value="<?= (int)$person['id'] ?>"><button class="btn btn-sm btn-outline-secondary">Toggle status</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></div>
<?php require dirname(__DIR__).'/includes/footer.php'; ?>
